def sign_plaintext_with_client(_signature_base_string, client):
    return sign_plaintext(client.client_secret, client.resource_owner_secret)


def sign_plaintext(client_secret, resource_owner_secret):
    return f"{client_secret}&{resource_owner_secret}"


def verify_plaintext(request, client_secret=None, resource_owner_secret=None):
    if not request.signature:
        return False
    expected = sign_plaintext(client_secret, resource_owner_secret)
    return safe_string_equals(request.signature, expected)
